package main

import (
    "context"
    "errors"
    "testing"
    "time"
)

type replicaFunc func(context.Context) (string, error)
func (f replicaFunc) Query(ctx context.Context) (string, error) { return f(ctx) }

func TestFirstSuccess(t *testing.T) {
    failed := replicaFunc(func(context.Context) (string, error) { return "", errors.New("unavailable") })
    success := replicaFunc(func(ctx context.Context) (string, error) {
        select { case <-time.After(10*time.Millisecond): return "winner", nil; case <-ctx.Done(): return "", ctx.Err() }
    })
    value, err := first(context.Background(), []Replica{failed, success, failed})
    if value != "winner" || err != nil { t.Fatalf("got %q, %v", value, err) }
}
func TestAllFailedAndEmpty(t *testing.T) {
    failed := replicaFunc(func(context.Context) (string, error) { return "", errors.New("unavailable") })
    for _, replicas := range [][]Replica{nil, {failed, failed}} {
        if _, err := first(context.Background(), replicas); err == nil { t.Fatal("expected an error") }
    }
}
func TestCallerCancellation(t *testing.T) {
    ctx, cancel := context.WithCancel(context.Background())
    cancel()
    wait := replicaFunc(func(ctx context.Context) (string, error) { <-ctx.Done(); return "", ctx.Err() })
    if _, err := first(ctx, []Replica{wait}); err == nil { t.Fatal("expected cancellation") }
}
func TestCancelsLosers(t *testing.T) {
    started, stopped := make(chan struct{}), make(chan struct{})
    loser := replicaFunc(func(ctx context.Context) (string, error) {
        close(started); <-ctx.Done(); close(stopped); return "", ctx.Err()
    })
    winner := replicaFunc(func(ctx context.Context) (string, error) {
        select { case <-started: return "winner", nil; case <-ctx.Done(): return "", ctx.Err() }
    })
    if _, err := first(context.Background(), []Replica{loser, winner}); err != nil { t.Fatal(err) }
    select { case <-stopped: case <-time.After(time.Second): t.Fatal("losing query was not cancelled") }
}

